package ioc; import packet.PacketMetadata; public final class MatchResult{private final Ioc ioc;private final PacketMetadata packet;private final String field;public MatchResult(Ioc ioc,PacketMetadata packet,String field){this.ioc=ioc;this.packet=packet;this.field=field;}public Ioc ioc(){return ioc;}public PacketMetadata packet(){return packet;}public String field(){return field;}public String format(){return ioc.type()+" "+ioc.value()+" matched "+field+" in "+packet.flowKey();}}
